const CYCLE = 8
const SLOT_PCT = 10
const RAMP_PCT = 2

function revealKeyframes(name: string, property: 'fill' | 'stroke', revealPct: number, dim: string, bright: string) {
  if (revealPct <= 0) {
    return `@keyframes ${name} { 0%, 100% { ${property}: ${bright}; } }`
  }
  const rampStart = Math.max(0, revealPct - RAMP_PCT)
  return `@keyframes ${name} {
    0% { ${property}: ${dim}; }
    ${rampStart}% { ${property}: ${dim}; }
    ${revealPct}% { ${property}: ${bright}; }
    100% { ${property}: ${bright}; }
  }`
}

