interface ProcessDiagramProps {
  className?: string
}

export function ProcessDiagram({ className }: ProcessDiagramProps) {
  return (
    <svg
      width="215"
      height="444"
      viewBox="0 0 215 444"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
    >
      <style>
        {NODES.map((_, i) =>
          revealKeyframes(`processNode${i}`, 'fill', i * 2 * SLOT_PCT, '#52525b', '#ffffff'),
        ).join('\n')}
        {LINES.map((_, i) =>
          revealKeyframes(`processLine${i}`, 'stroke', (i * 2 + 1) * SLOT_PCT, '#52525b', '#ffffff'),
        ).join('\n')}
      </style>
      <g opacity={0.3}>
        <mask
          id="process-watermark-mask"
          maskUnits="userSpaceOnUse"
          x="58.2969"
          y="4.62891"
          width="71"
          height="439"
          fill="black"
        >
          <rect fill="white" x="58.2969" y="4.62891" width="71" height="439" />
          <path d={WATERMARK_MASK_PATH} />
        </mask>
        <path d={WATERMARK_OUTLINE_PATH} fill="white" mask="url(#process-watermark-mask)" />
      </g>

      {NODES.map((node, i) => {
        const anim = `processNode${i} ${CYCLE}s linear infinite`
        return (
          <g key={node.label}>
            <circle cx={node.cx} cy={node.cy} r={9.31418} style={{ animation: anim, fill: '#52525b' }} />
            <path d={node.path} style={{ animation: anim, fill: '#52525b' }} />
          </g>
        )
      })}

      {LINES.map((line, i) => (
        <line
          key={`${line.x1}-${line.y1}`}
          x1={line.x1}
          y1={line.y1}
          x2={line.x2}
          y2={line.y2}
          strokeWidth={1.86284}
          strokeDasharray="3.73 3.73"
          style={{
            animation: `processLine${i} ${CYCLE}s linear infinite`,
            stroke: '#52525b',
          }}
        />
      ))}
    </svg>
  )
}
